SOURCE_INPUTS={'changer': {'sha256': '242bad23ac8afffbb8bf3be1a57166ae006f4a9292d8eea35322b372b1466d75', 'compressed': ''}, 'balancer': {'sha256': '107884b8686b8c0e9bea0e164ded2b41c4fb8a7338f725c25f1dd78335061961', 'compressed': ''}, 'jack': {'sha256': '572fc00fee865f6cdbe66e8e4a92cb9f137460f118dfd04e0daa9fdf37f05b21', 'compressed': ''}}
